"use strict";(globalThis.webpackChunkgrc||=[]).push([[72803],{74438(e){e.exports=JSON.parse('[{"citeKey":"rajesh2026explainability","slug":"rajesh-2026-io-observability-explainability-2bb9","title":"Extending I/O Observability to Explainability for Targeted Optimization","authors":["N. Rajesh","S. Neuwirth","J. Lofstead","A. Kougkas","X.-H. Sun","N. Dryden","H. Devarajan"],"venue":"International Conference for High Performance Computing, Networking, Storage, and Analysis (SC 2026)","type":"Poster","entryType":"misc","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=rpost229&sess=sess313"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"devarajan2026orion","slug":"devarajan-2026-orion-1c17","title":"Orion: Observability framework for hybrid workflow-centric I/O monitoring in HPC systems","authors":["H. Devarajan","R. A. O. Sinurat","I. Yildirim","O. Kogiou","A. Marathe","N. Dryden"],"venue":"8th Workshop on Programming and Performance Visualization Tools (ProTools 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_prot104&sess=sess131"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"devarajan2026datacrumbs","slug":"devarajan-2026-datacrumbs-11c5","title":"DataCrumbs: Efficient Cross-Layer Data Capture for Explainable I/O Performance in HPC Storage Stacks","authors":["H. Devarajan","S. Neuwirth","C. Wang","R. A. O. Sinurat","N. Rajesh","J. Lofstead","V. Sochat","D. Milroy","T. Scogland"],"venue":"8th Workshop on Programming and Performance Visualization Tools (ProTools 2026), held in conjunction with SC26","type":"Workshop","entryType":"inproceedings","date":"November, 2026","year":2026,"era":"iit","month":11,"hasAbstract":false,"links":{"program":"https://sc26.conference-program.com/presentation/?id=ws_prot105&sess=sess131"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"accepted","visibility":"public"},{"citeKey":"lumsden2025optimizing","slug":"lumsden-2025-optimizing-rex5","title":"Optimizing I/O for an Exascale Implicit Kinetic Plasma Simulation using the Rabbit Storage System","authors":["I. Lumsden","H. Devarajan","I. Yildirim","S. Markidis","A. Hu","I. Peng","L. Pennati","D. Yokelson","S. Brink","O. Pearce","T. Scogland","B. R. de Supinski","G. L. Delzanno","A. Kougkas","X.-H. Sun","M. Taufer"],"venue":"REX-IO 2025 in conjunction with IEEE Cluster 2025 in Edinburgh, Scotland","type":"Workshop","entryType":"inproceedings","date":"September, 2025","year":2025,"era":"iit","month":9,"doi":"10.1109/CLUSTERWorkshops65972.2025.11164212","hasAbstract":false,"pages":"1\u20136","links":{"pdf":"https://grc.iit.edu/papers/2025/lumsden-2025-optimizing-rex5.pdf"},"tags":["HPC","Rabbit Nodes","I/O Accelerators","I/O Optimization","iPIC3D","IOR"],"_projectIds":[],"_funding":[{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2025wisio","slug":"yildirim-2025-wisio-45f7","title":"WisIO: Automated I/O Bottleneck Detection with Multi-Perspective Views for HPC Workflows","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The 39th ACM International Conference on Supercomputing (ICS 2025)","type":"Conference","entryType":"inproceedings","date":"June, 2025","year":2025,"era":"iit","month":6,"doi":"10.1145/3721145.3725742","abstract":"Modern HPC workloads involve large data transfers that can become bottlenecks. Existing analysis tools identify bottle- necks from per-file performance data but have limitations in parallelizability and rigid heuristic-based rules, necessitating an automated, efficient, and multi-perspective solution. We designed an automated tool, WisIO, that enables parallel and distributed analysis of multi-terabyte-scale workflow performance data. WisIO examines performance data from multiple perspectives, uses metric-driven bottleneck classifi- cation, and allows extensible mapping of bottlenecks to root causes. Experimental results demonstrate that WisIO\'s multi- perspective views substantially improve bottleneck coverage, showing an average increase of up to 805\xd7 when compared to analyzing performance data from a single perspective. In our performance evaluation, WisIO\'s metric-driven classification processed 340K bottlenecks per second, while its reasoning engine handled around 35K bottlenecks per sec- ond. In an analysis of five real-world HPC workloads, WisIO demonstrated up to 11\xd7 faster analysis time and identified up to 144x more bottlenecks compared to existing solutions.","hasAbstract":true,"lede":"Modern HPC workloads involve large data transfers that can become bottlenecks.","links":{"pdf":"https://grc.iit.edu/papers/2025/yildirim-2025-wisio-45f7.pdf"},"tags":["HPC","Workflows","I/O Analysis","I/O Bottleneck Detection","WisIO","LABIOS"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-2313154","agencyKnown":true},{"agency":"NSF","award":"OAC-2411318","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2024dftracer","slug":"devarajan-2024-dftracer-8fcb","title":"DFTracer: An Analysis-Friendly Data Flow Tracer for AI-Driven Workflows","authors":["H. Devarajan","L. Pottier","K. Velusamy","H. Zheng","I. Yildirim","O. Kogiou","W. Yu","A. Kougkas","X.-H. Sun","J.-S. Yeom","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'24)","type":"Conference","entryType":"inproceedings","date":"November, 2024","year":2024,"era":"iit","month":11,"doi":"10.1109/sc41406.2024.00023","abstract":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight. These workflows require a cohesive set of performance analysis tools to provide a comprehensive understanding of data exchange patterns in HPC systems. However, current tools are not designed to work with an AI-based I/O software stack that requires tracing at multiple levels of the application. To this end, we developed a data flow tracer called DFTracer to capture data-centric events from workflows and the I/O stack to build a detailed understanding of the data exchange within AI-driven workflows. DFTracer has the following three novel features, including a unified interface to capture trace data from different layers in the software stack, a trace format that is analysis-friendly and optimized to support efficiently loading multi-million events in a few seconds, and the capability to tag events with workflow-specific context to perform domain-centric data flow analysis for workflows. Additionally, we demonstrate that DFTracer has a 1.44x smaller runtime overhead and 1.3-7.1x smaller trace size than state-of-the-art tracing tools such as Score-P, Recorder, and Darshan. Moreover, with AI-driven workflows, Score-P, Recorder, and Darshan cannot find I/O accesses from dynamically spawned processes, and their load performance of 100M events is three orders of magnitude slower than DFTracer. In conclusion, we demonstrate that DFTracer can capture multi-level performance data, including contextual event tagging with a low overhead of 1-5% from AI-driven workflows such as MuMMI and Microsoft\'s Megatron Deepspeed running on large-scale HPC systems. Index Terms-deep learning, workflows, I/O, tracer, multi- level, application apis, system calls, transparent, interception.","hasAbstract":true,"lede":"Modern HPC workflows involve intricate coupling of simulation, data analytics, and artificial intelligence (AI) applications to improve time to scientific insight.","links":{"pdf":"https://grc.iit.edu/papers/2024/devarajan-2024-dftracer-8fcb.pdf"},"tags":["Deep Learning","Workflows","I/O Tracing"],"_projectIds":["wisio"],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true},{"agency":"NIH","award":"75N91019D00024","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023exploringimpacts","slug":"yildirim-2023-exploring-impacts-090b","title":"Exploring the Impacts of Multiple I/O Metrics in Identifying I/O Bottlenecks","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'23), November 12-17, 2023","type":"Technical Report","entryType":"misc","date":"November, 2023","year":2023,"era":"iit","month":11,"hasAbstract":false,"links":{"poster":"https://grc.iit.edu/papers/2023/yildirim-2023-exploring-impacts-090b-poster.pdf"},"tags":["I/O Analysis","I/O Metrics","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2023iomax","slug":"yildirim-2023-iomax-3919","title":"IOMax: Maximizing Out-of-Core I/O Analysis Performance on HPC Systems","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Parallel Data Systems Workshop (PDSW\'23)","type":"Workshop","entryType":"inproceedings","date":"November, 2023","year":2023,"era":"iit","month":11,"doi":"10.1145/3624062.3624191","abstract":"I/O analysis is an essential task for improving the performance of scientific applications on high-performance computing (HPC) systems. However, current analysis tools, which often use data drilling techniques (iterative exploration for deeper insights), treat every query independently and do not optimize column data for data-slicing (extracting specific data subsets), resulting in subpar querying performance. In this paper, we designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces. IOMax utilizes a novel query optimization technique to improve the query performance by 8.6x while reducing the memory footprint required for analysis by 11x. Additionally, it employs data transformation techniques to improve data-slicing performance by up to 11.4x. In conclusion, IOMax optimizes I/O analysis for scientific workflows on the Lassen supercomputer, resulting in up to 7x improvement.","hasAbstract":true,"lede":"We designed IOMax, a tool for efficient data drilling analysis on large-scale I/O traces.","links":{"pdf":"https://grc.iit.edu/papers/2023/yildirim-2023-iomax-3919.pdf"},"tags":["I/O Analysis","Out-of-Core Analysis","Data Drilling","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"LLNL","award":"DE-AC52-07NA27344","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"yildirim2022multifacetedapproach","slug":"yildirim-2022-multifaceted-approach-da2d","title":"A Multifaceted Approach to Automated I/O Bottleneck Detection for HPC Workloads","authors":["I. Yildirim","H. Devarajan","A. Kougkas","X.-H. Sun","K. Mohror"],"venue":"The International Conference for High Performance Computing, Networking, Storage, and Analysis (SC\'22)","type":"Poster","entryType":"misc","date":"November, 2022","year":2022,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d.pdf","poster":"https://grc.iit.edu/papers/2022/yildirim-2022-multifaceted-approach-da2d-poster.pdf"},"tags":["I/O Characterization","I/O Bottleneck Detection","WisIO"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-2104013","agencyKnown":true},{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2022stimulus","slug":"devarajan-2022-stimulus-4b4c","title":"Stimulus: Accelerate Data Management for Scientific AI applications in HPC","authors":["H. Devarajan","A. Kougkas","H. Zheng","V. Vishwanath","X.-H. Sun"],"venue":"The 22nd IEEE/ACM International Symposium on Cluster, Cloud and Internet Computing (CCGRID\'22), May 16-19, 2022","type":"Conference","entryType":"inproceedings","date":"May, 2022","year":2022,"era":"iit","month":5,"doi":"10.1109/ccgrid54584.2022.00020","abstract":"Modern scientific workflows couple simulations with AI-powered analytics by frequently exchanging data to accelerate time-to-science to reduce the complexity of the simulation planes. However, this data exchange is limited in performance and portability due to a lack of support for scientific data formats in AI frameworks. We need a cohesive mechanism to effectively integrate at scale complex scientific data formats such as HDF5, PnetCDF, ADIOS2, GNCF, and Silo into popular AI frameworks such as TensorFlow, PyTorch, and Caffe. To this end, we designed Stimulus, a data management library for ingesting scientific data effectively into the popular AI frameworks. We utilize the StimOps functions along with StimPack abstraction to enable the integration of scientific data formats with any AI framework. The evaluations show that Stimulus outperforms several large-scale applications with different use-cases such as Cosmic Tagger (con- suming HDF5 dataset in PyTorch), Distributed FFN (consuming HDF5 dataset in TensorFlow), and CosmoFlow (converting HDF5 into TFRecord and then consuming that in TensorFlow) by 5.3x, 2.9x, and 1.9\xd7 respectively with ideal I/O scalability up to 768 GPUs on the Summit supercomputer. Through Stimulus, we can portably extend existing popular AI frameworks to cohesively support any complex scientific data format and efficiently scale the applications on large-scale supercomputers.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2022/devarajan-2022-stimulus-4b4c.pdf"},"tags":["HDF5","TensorFlow","Decoupled I/O","I/O Acceleration","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2021hflow","slug":"cernuda-2021-hflow-2f5b","title":"HFlow: A Dynamic and Elastic Multi-Layered Data Forwarder","authors":["J. Cernuda","H. Devarajan","L. Logan","K. Bateman","N. Rajesh","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 2021 IEEE International Conference on Cluster Computing (CLUSTER\'21), September 7-10, 2021","type":"Conference","entryType":"inproceedings","date":"September, 2021","year":2021,"era":"iit","month":9,"doi":"10.1109/cluster48925.2021.00064","abstract":"Modern applications are highly data-intensive, leading to the well-known I/O bottleneck problem. Scientists have proposed the placement of fast intermediate storage resources which aim to mask the I/O penalties. To manage these resources, three core software abstractions are being used in leadership-class computing facilities: IO Forwarders, Burst Buffers, and Data Stagers. Yet, with the rise of multi-tenant deployment in HPC systems, these software abstractions are: managed and maintained in isolation, leading to inefficient interactions; allocated statically, leading to load imbalance; exclusively bifurcated between the intermediate storage, leading to under-utilization of resources, and, in many cases, do not support in-situ operations. To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm. HFlow introduces a unified data movement abstraction (the ByteFlow) providing data-independent tasks that can be executed anywhere and thus, enabling dynamic resource provisioning. Moreover, the processing elements executing the ByteFlows are designed to be ephemeral and, hence, enable elastic management of intermediate storage resources. Our results show that applications running under HFlow display an increase in performance of 3x when compared with state-of-the-art software solutions. Index Terms-Data streaming, I/O forwarding, elasticity, dynamicity, multi-tenant, data-intensive, I/O,data pipeline, in-transit","hasAbstract":true,"lede":"To this end, we present HFlow, a new class of data forwarding system that leverages a real-time data movement paradigm.","links":{"pdf":"https://grc.iit.edu/papers/2021/cernuda-2021-hflow-2f5b.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"rajesh2021apollo","slug":"rajesh-2021-apollo-dbd8","title":"Apollo: An ML-assisted Real-Time Storage Resource Observer","authors":["N. Rajesh","H. Devarajan","J. Cernuda","K. Bateman","L. Logan","J. Ye","A. Kougkas","X.-H. Sun"],"venue":"The 30th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'21), June 21-25, 2021","type":"Conference","entryType":"inproceedings","date":"June, 2021","year":2021,"era":"iit","month":6,"doi":"10.1145/3431379.3460640","abstract":"Applications and middleware services, such as data placement en- gines, I/O scheduling, and prefetching engines, require low-latency access to telemetry data in order to make optimal decisions. However, typical monitoring services store their telemetry data in a database in order to allow applications to query them, resulting in significant latency penalties. This work presents Apollo: a low-latency mon- itoring service that aims to provide applications and middleware libraries with direct access to relational telemetry data. Monitoring the system can create interference and overhead, slowing down raw performance of the resources for the job. However, having a current view of the system can aid middleware services in making more optimal decisions which can ultimately improve the overall perfor- mance. Apollo has been designed from the ground up to provide low latency, using Publish\u2013Subscribe (Pub-Sub) semantics, and low overhead, using adaptive intervals in order to change the length of time between polling the resource for telemetry data and machine learning in order to predict changes to the telemetry data between actual resource polling. This work also provides some high level abstractions called I/O curators, which can further aid middleware libraries and applications to make optimal decisions. Evaluations showcase that Apollo can achieve sub-millisecond latency for acquir- ing complex insights with a memory overhead of 57MB and CPU overhead being only 7% more than existing state-of-the-art systems.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2021/rajesh-2021-apollo-dbd8.pdf"},"tags":["HPC","Machine Learning","Resource Monitoring","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2021dlio","slug":"devarajan-2021-dlio-0272","title":"DLIO: A Data-Centric Benchmark for Scientific Deep Learning Applications","authors":["H. Devarajan","H. Zheng","A. Kougkas","X.-H. Sun","V. Vishwanath"],"venue":"The 2021 IEEE/ACM International Symposium in Cluster, Cloud, and Internet Computing (CCGrid\'21), May 17 - 20, 2021 Best paper award","type":"Conference","entryType":"inproceedings","date":"May, 2021","year":2021,"era":"iit","month":5,"doi":"10.1109/ccgrid51090.2021.00018","abstract":"Deep learning has been shown as a successful method for various tasks, and its popularity results in numerous open-source deep learning software tools. Deep learning has been applied to a broad spectrum of scientific domains such as cosmology, particle physics, computer vision, fusion, and astrophysics. Scientists have performed a great deal of work to optimize the computational performance of deep learning frameworks. However, the same cannot be said for I/O perfor- mance. As deep learning algorithms rely on big-data volume and variety to effectively train neural networks accurately, I/O is a significant bottleneck on large-scale distributed deep learning training. This study aims to provide a detailed investigation of the I/O behavior of various scientific deep learning workloads running on the Theta supercomputer at Argonne Leadership Computing Facility. In this paper, we present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads. DLIO can be utilized to accurately emulate the I/O behavior of modern scientific deep learning applications. Using DLIO, application developers and system software solution architects can identify potential I/O bottlenecks in their applications and guide optimizations to boost the I/O performance leading to lower training times by up to 6.7x.","hasAbstract":true,"lede":"We present DLIO, a novel representative benchmark suite built based on the I/O profiling of the selected workloads.","links":{"pdf":"https://grc.iit.edu/papers/2021/devarajan-2021-dlio-0272.pdf","video":"https://youtu.be/_rRhQBaHVs8"},"tags":["Deep Learning","Scientific Applications","Representative","Benchmark","Data-Intensive","I/O","Characterization","TensorFlow","Data Pipeline","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Best Paper Award (First Prize)","status":"published","visibility":"public"},{"citeKey":"devarajan2020hreplica","slug":"devarajan-2020-hreplica-44a8","title":"HReplica: A Dynamic Data Replication Engine with Adaptive Compression for Multi-Tiered Storage","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The 2020 IEEE International Conference on Big Data (Big Data\'20), December 10-13, 2020","type":"Conference","entryType":"inproceedings","date":"December, 2020","year":2020,"era":"iit","month":12,"doi":"10.1109/bigdata50022.2020.9378167","abstract":"As the diversity of big data applications increases, their requirements diverge and often conflict with one other. Managing this diversity in any supercomputer or data center is a major challenge for system designers. Data replication is a popular approach to meet several of these requirements, such as low latency, read availability, durability, etc. This approach can be enhanced using new modern heterogeneous hardware and soft- ware techniques such as data compression. However, both these enhancements work in isolation to the detriment of both. In this work, we present HReplica: a dynamic data replication engine which harmoniously leverages data compression and hierarchical storage to increase the effectiveness of data replication. We have developed a novel dynamic selection algorithm that facilitates the optimal matching of replication schemes, compression libraries, and tiered storage. Our evaluation shows that HReplica can improve scientific and cloud application performance by 5.2x when compared to other state-of-the-art replication schemes. Index Terms-data replication, dynamic, selection algorithm, multi-tiered, data compression, intelligent selection, dynamic programming, cloud application, scientific application, big data.","hasAbstract":true,"lede":"We present HReplica: a dynamic data replication engine which harmoniously leverages data compression and hierarchical storage to increase the effectiveness of data replication.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hreplica-44a8.pdf"},"tags":["Data Replication","Dynamic","Selection Algorithm","Multi-Tiered","Data Compression","Intelligent Selection","Dynamic Programming","Cloud Application","Scientific Applications","Big Data","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020dynamicmulti","slug":"devarajan-2020-dynamic-multi-ef19","title":"A Dynamic Multi-Tiered Storage System for Extreme Scale Computing","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19-slides.pdf","poster":"https://grc.iit.edu/papers/2020/devarajan-2020-dynamic-multi-ef19-poster.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020understandingio","slug":"devarajan-2020-understanding-io-755d","title":"Understanding I/O behavior of Scientific Deep Learning Applications in HPC systems","authors":["H. Devarajan","H. Zheng","X.-H. Sun","V. Vishwanath"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'20)","type":"Poster","entryType":"misc","date":"November, 2020","year":2020,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-understanding-io-755d.pdf","poster":"https://grc.iit.edu/papers/2020/devarajan-2020-understanding-io-755d-poster.pdf"},"_projectIds":[],"_funding":[{"agency":"ANL","award":"DE-AC02-06CH11357","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020bridgingstorage","slug":"kougkas-2020-bridging-storage-5e1c","title":"Bridging Storage Semantics using Data Labels and Asynchronous I/O","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"ACM Transactions on Storage (TOS\'20), Vol 16, No 4, Article 22, Nov. 2020","type":"Journal","entryType":"article","date":"November, 2020","year":2020,"era":"iit","month":11,"doi":"10.1145/3415579","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting requirements. Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elasticity, and promotes in-situ analytics and software defined storage support via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"lede":"Further, new hardware technologies and system designs create a hierarchical composition that may be ideal for computational storage operations.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-bridging-storage-5e1c.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage"],"_projectIds":[],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020chronolog","slug":"kougkas-2020-chronolog-c458","title":"ChronoLog: A Distributed Shared Tiered Log Store with Time-based Data Ordering","authors":["A. Kougkas","H. Devarajan","K. Bateman","J. Cernuda","N. Rajesh","X.-H. Sun"],"venue":"The 36th International Conference on Massive Storage Systems and Technology (MSST\'20), Oct. 29-30, 2020","type":"Conference","entryType":"inproceedings","date":"October, 2020","year":2020,"era":"iit","month":10,"abstract":"Modern applications produce and process massive amounts of activity (or log) data. Traditional storage systems were not designed with an append-only data model and a new storage abstraction aims to fill this gap: the distributed shared log store. However, existing solutions struggle to provide a scalable, parallel, and high-performance solution that can support a diverse set of conflicting log workload requirements. Finding the tail of a distributed log is a centralized point of contention. In this paper, we show how using physical time can help alleviate the need of centralized synchronization points. We present ChronoLog, a new, distributed, shared, and multi-tiered log store that can handle more than a million tail operations per second. Evaluation results show ChronoLog\'s potential, outperforming existing solution by an order of magnitude.","hasAbstract":true,"lede":"We show how using physical time can help alleviate the need of centralized synchronization points.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-chronolog-c458.pdf"},"tags":["Distributed Log","Shared Log","Tiered Storage","ChronoLog"],"_projectIds":["chronolog"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcl","slug":"devarajan-2020-hcl-d2f4","title":"HCL: Distributing Parallel Data Structures in Extreme Scales","authors":["H. Devarajan","A. Kougkas","K. Bateman","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing (CLUSTER\'20), Sept. 14-17, 2020","type":"Conference","entryType":"inproceedings","date":"September, 2020","year":2020,"era":"iit","month":9,"doi":"10.1109/cluster49012.2020.00035","abstract":"Most parallel programs use irregular control flow and data structures, which are perfect for one-sided communication paradigms such as MPI or PGAS programming languages. However, these environments lack the presence of efficient function-based application libraries that can utilize popular communication fabrics such as TCP, Infinity Band (IB), and RDMA over Converged Ethernet (RoCE). Additionally, there is a lack of high-performance data structure interfaces. We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues. HCL uses a RPC over RDMA technology that implements a novel procedural programming paradigm. In this paper, we argue a RPC over RDMA technology can serve as a high-performance, flexible, and co-ordination free backend for implementing complex data structures. Evaluation results from testing real workloads shows that HCL programs are 2x to 12x faster compared to BCL, a state-of-the-art distributed data structure library.","hasAbstract":true,"lede":"We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4-slides.pdf"},"tags":["Distributed Data Structure","RPC over RDMA","Hybrid Data Access Model","HPC Data Containers","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hcompress","slug":"devarajan-2020-hcompress-70f7","title":"HCompress: Hierarchical Data Compression for Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","L. Logan","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00064","abstract":"Modern scientific applications read and write massive amounts of data through simulations, observations, and analysis. These applications spend the majority of their runtime in performing I/O. HPC storage solutions include fast node-local and shared storage resources to elevate applications from this bottleneck. Moreover, several middleware libraries (e.g., Hermes) are proposed to move data between these tiers transparently. Data reduction is another technique that reduces the amount of data produced and, hence, improve I/O performance. These two technologies, if used together, can benefit from each other. The effectiveness of data compression can be enhanced by selecting different compression algorithms according to the characteristics of the different tiers, and the multi-tiered hierarchy can benefit from extra capacity. In this paper, we design and implement HCompress, a hierarchical data compression library that can improve the application\'s performance by harmoniously leveraging both multi-tiered storage and data compression. We have developed a novel compression selection algorithm that facilitates the optimal matching of compression libraries to the tiered storage. Our evaluation shows that HCompress can improve scientific application\'s performance by 7x when compared to other state-of-the-art tiered storage solutions.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcompress-70f7-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Compression","Data-Reduction","Dynamic Choice","Workflow Priorities","Library","Middleware","Engine","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2020hfetch","slug":"devarajan-2020-hfetch-46e9","title":"HFetch: Hierarchical Data Prefetching for Scientific Workflows in Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE International Parallel and Distributed Processing Symposium (IPDPS\'20), May 18-22, 2020","type":"Conference","entryType":"inproceedings","date":"May, 2020","year":2020,"era":"iit","month":5,"doi":"10.1109/ipdps47924.2020.00017","abstract":"In the era of data-intensive computing, accessing data with a high-throughput and low-latency is more imperative than ever. Data prefetching is a well-known technique for hiding read latency. However, existing solutions do not consider the new deep memory and storage hierarchy and also suffer from under-utilization of prefetching resources and unnecessary evictions. Additionally, existing approaches implement a client- pull model where understanding the application\'s I/O behavior drives prefetching decisions. Moving towards exascale, where machines run multiple applications concurrently by accessing files in a workflow, a more data-centric approach can resolve challenges such as cache pollution and redundancy. In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching. We demonstrate the benefits of such an approach. Results show 10- 35% performance gains over existing prefetchers and over 50% when compared to systems with no prefetching.","hasAbstract":true,"lede":"In this study, we present HFetch, a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hfetch-46e9-slides.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Prefetching","Data-Fetching","Dynamic Choice","Data-Centric","Library","Middleware","Engine","Data-Aware","Workflow-Aware","Server-Push","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2020ioacceleration","slug":"kougkas-2020-io-acceleration-4458","title":"I/O Acceleration via Multi-Tiered Data Buffering and Prefetching","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"Journal of Computer Science and Technology (JCST\'20), vol 35. no 1. pp 92-120","type":"Journal","entryType":"article","date":"January, 2020","year":2020,"era":"iit","month":1,"doi":"10.1007/s11390-020-9781-1","abstract":"Modern High-Performance Computing (HPC) systems are adding extra layers to the memory and storage hierarchy, named deep memory and storage hierarchy (DMSH), to increase I/O performance. New hardware technologies, such as NVMe and SSD, have been introduced in burst buffer installations to reduce the pressure for external storage and boost the burstiness of modern I/O systems. The DMSH has demonstrated its strength and potential in practice. However, each layer of DMSH is an independent heterogeneous system and data movement among more layers is significantly more complex even without considering heterogeneity. How to efficiently utilize the DMSH is a subject of research facing the HPC community. Further, accessing data with a high-throughput and low-latency is more imperative than ever. Data prefetching is a well-known technique for hiding read latency by requesting data before it is needed to move it from a high-latency medium (e.g., disk) to a low-latency one (e.g., main memory). However, existing solutions do not consider the new deep memory and storage hierarchy and also suffer from under-utilization of prefetching resources and unnecessary evictions. Additionally, existing approaches implement a client-pull model where understanding the application\'s I/O behavior drives prefetching decisions. Moving towards exascale, where machines run multiple applications concurrently by accessing files in a workflow, a more data-centric approach resolves challenges such as cache pollution and redundancy. In this paper, we present the design and implementation of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system. Hermes enables, manages, supervises, and, in some sense, extends I/O buffering to fully integrate into the DMSH. We introduce three novel data placement policies to efficiently utilize all layers and we present three novel techniques to perform memory, metadata, and communication management in hierarchical buffering systems. Additionally, we demonstrate the benefits of a truly hierarchical data prefetcher that adopts a server-push approach to data prefetching. Our evaluation shows that, in addition to automatic data movement through the hierarchy, Hermes can significantly accelerate I/O and outperforms by more than 2x state-of-the-art buffering platforms. Lastly, results show 10%-35% performance gains over existing prefetchers and over 50% when compared to systems with no prefetching.","hasAbstract":true,"lede":"We present the design and implementation of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system.","links":{"pdf":"https://grc.iit.edu/papers/2020/kougkas-2020-io-acceleration-4458.pdf"},"tags":["I/O Buffering","Heterogeneous Buffering","Layered Buffering","Deep Memory Hierarchy","Burst Buffers","Hierarchical Data Prefetching","Data-Centric Architecture","Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"feng2019niobe","slug":"feng-2019-niobe-19f9","title":"NIOBE: An Intelligent I/O Bridging Engine for Complex and Distributed Workflows","authors":["K. Feng","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The 7th IEEE International Conference on Big Data, 2019. pp. 493-502","type":"Conference","entryType":"inproceedings","date":"December, 2019","year":2019,"era":"iit","month":12,"doi":"10.1109/bigdata47090.2019.9006363","abstract":"In the age of data-driven computing, integrating High Performance Computing (HPC) and Big Data (BD) en- vironments may be the key to increasing productivity and to driving scientific discovery forward. Scientific workflows consist of diverse applications (i.e., HPC simulations and BD analysis) each with distinct representations of data that introduce a se- mantic barrier between the two environments. To solve scientific problems at scale, accessing semantically different data from different storage resources is the biggest unsolved challenge. In this work, we aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\". We propose iNtelligent I/O Bridging Engine (NIOBE), a new data integration framework that enables integrated data access for scientific workflows with asynchronous I/O and data aggregation. NIOBE performs the data integration using available I/O resources, in contrast to existing optimizations that ignore the I/O nodes present on the data path. In NIOBE, data access is optimized to consider both the ongoing production and the consumption of the data in the future. Experimental results show that with NIOBE, an integrated scientific workflow can be accelerated by up to 10x when compared to a no-integration baseline and by up to 133% compared to other state-of-the-art integration solutions.","hasAbstract":true,"lede":"We aim to address a critical question: \\"How can we exploit the existing resources and efficiently provide transparent access to data from/to both environments\\".","links":{"pdf":"https://grc.iit.edu/papers/2019/feng-2019-niobe-19f9.pdf"},"tags":["Data Integration","Integrated Workflow","Data Aggregation","KVS","Parallel File System (PFS)"],"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"cernuda2019efficientdata","slug":"cernuda-2019-efficient-data-b08d","title":"Efficient Data Eviction across Multiple Tiers of Storage","authors":["J. Cernuda","H. Trivino","H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'19)","type":"Poster","entryType":"misc","date":"November, 2019","year":2019,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d.pdf","poster":"https://grc.iit.edu/papers/2019/cernuda-2019-efficient-data-b08d-poster.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2019hfetch","slug":"devarajan-2019-hfetch-980e","title":"HFetch: Hierarchical Data Prefetching in Multi-Tiered Storage Environments","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"The International Conference for High Performance Computing, Networking, Storage and Analysis (SC\'19) Best Poster Nominee, Ph.D Forum","type":"Poster","entryType":"misc","date":"November, 2019","year":2019,"era":"iit","month":11,"hasAbstract":false,"links":{"pdf":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e.pdf","slides":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e-slides.pdf","poster":"https://grc.iit.edu/papers/2019/devarajan-2019-hfetch-980e-poster.pdf"},"tags":["Hierarchical","Multi-Tiered","Data Prefetching","Server-Centric","Data-Centric","File Scoring","Data Scoring","Workflow-Aware","Lightweight","Server-Side","Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2019labios","slug":"kougkas-2019-labios-8411","title":"LABIOS: A Distributed Label-Based I/O System","authors":["A. Kougkas","H. Devarajan","J. Lofstead","X.-H. Sun"],"venue":"The 28th International Symposium on High-Performance Parallel and Distributed Computing (HPDC\'19), Phoenix, USA 2019. pp. 13-24. Karsten Schwan Best Paper Award","type":"Conference","entryType":"inproceedings","date":"June, 2019","year":2019,"era":"iit","month":6,"doi":"10.1145/3307681.3325405","abstract":"In the era of data-intensive computing, large-scale applications, in both scientific and the BigData communities, demonstrate unique I/O requirements leading to a proliferation of different storage devices and software stacks, many of which have conflicting re- quirements. In this paper, we investigate how to support a wide variety of conflicting I/O workloads under a single storage system. We introduce the idea of a Label, a new data representation, and, we present LABIOS: a new, distributed, Label- based I/O system. LABIOS boosts I/O performance by up to 17x via asynchronous I/O, supports heterogeneous storage resources, offers storage elastic- ity, and promotes in-situ analytics via data provisioning. LABIOS demonstrates the effectiveness of storage bridging to support the convergence of HPC and BigData workloads on a single platform.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411.pdf","slides":"https://grc.iit.edu/papers/2019/kougkas-2019-labios-8411-slides.pdf"},"tags":["Label-Based I/O","Storage Bridging","Heterogeneous I/O","Datalabels","Task-Based I/O","Exascale I/O","Energy-Aware I/O","Elastic Storage","Hermes"],"_projectIds":["hermes","labios"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"CCF-1744317","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CNS-1526887","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"grcAwards":"Karsten Schwan Best Paper Award","status":"published","visibility":"public"},{"citeKey":"devarajan2019intelligent","slug":"devarajan-2019-intelligent--e9fd","title":"An Intelligent, Adaptive, and Flexible Data Compression Framework","authors":["H. Devarajan","A. Kougkas","X.-H. Sun"],"venue":"IEEE/ACM International Symposium in Cluster, Cloud, and Grid Computing (CCGrid\'19), Larnaca, Cyprus2019. pp. 82-91.","type":"Conference","entryType":"inproceedings","date":"May, 2019","year":2019,"era":"iit","month":5,"doi":"10.1109/ccgrid.2019.00019","abstract":"The data explosion phenomenon in modern appli- cations causes tremendous stress on storage systems. Developers use data compression, a size-reduction technique, to address this issue. However, each compression library exhibits different strengths and weaknesses when considering the input data type and format. We present Ares, an intelligent, adaptive, and flexible compression framework which can dynamically choose a compression library for a given input data based on the type of the workload and provides an appropriate infrastructure to users to fine-tune the chosen library. Ares is a modular framework which unifies several compression libraries while allowing the addition of more compression libraries by the user. Ares is a unified compression engine that abstracts the complexity of using different compression libraries for each workload. Evaluation results show that under real-world applications, from both scientific and Cloud domains, Ares performed 2-6x faster than competitive solutions with a low cost of additional data analysis (i.e., overheads around 10%) and up to 10x faster against a baseline of no compression at all.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd.pdf","slides":"https://grc.iit.edu/papers/2019/devarajan-2019-intelligent--e9fd-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[{"agency":"NSF","award":"OAC-1835764","agencyKnown":true},{"agency":"NSF","award":"CSR-1814872","agencyKnown":true},{"agency":"NSF","award":"CCF-1744317","agencyKnown":true},{"agency":"NSF","award":"CNS-1730488","agencyKnown":true},{"agency":"NSF","award":"CNS-1526887","agencyKnown":true}],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2018vidya","slug":"devarajan-2018-vidya-e65b","title":"Vidya: Performing Code-Block I/O Characterization for Data Access Optimization","authors":["H. Devarajan","A. Kougkas","P. Challa","X.-H. Sun"],"venue":"The IEEE International Conference on High Performance Computing, Data, and Analytics 2018 (HiPC\'18), Bengaluru, India2018. pp. 255-264.","type":"Conference","entryType":"inproceedings","date":"December, 2018","year":2018,"era":"iit","month":12,"doi":"10.1109/hipc.2018.00036","abstract":"Understanding, characterizing and tuning scientific applications\' I/O behavior is an increasingly complicated process in HPC systems. Existing tools use either offline profiling or online analysis to get insights into the applications\' I/O patterns. However, there is lack of a clear formula to characterize applica- tions\' I/O. Moreover, these tools are application specific and do not account for multi-tenant systems. This paper presents Vidya, an I/O profiling framework which can predict application\'s I/O intensity using a new formula called Code-Block I/O Character- ization (CIOC). Using CIOC, developers and system architects can tune an application\'s I/O behavior and better match the underlying storage system to maximize performance. Evaluation results show that Vidya can predict an application\'s I/O intensity with a variance of 0.05%. Vidya can profile applications with a high accuracy of 98% while reducing profiling time by 9x. We further show how Vidya can optimize an application\'s I/O time by 3.7x.","hasAbstract":true,"lede":"This paper presents Vidya, an I/O profiling framework which can predict application\'s I/O intensity using a new formula called Code-Block I/O Character- ization (CIOC).","links":{"pdf":"https://grc.iit.edu/papers/2018/devarajan-2018-vidya-e65b.pdf","slides":"https://grc.iit.edu/papers/2018/devarajan-2018-vidya-e65b-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018harmonia","slug":"kougkas-2018-harmonia-5ca9","title":"Harmonia: An Interference-Aware Dynamic I/O Scheduler for Shared Non-Volatile Burst Buffers","authors":["A. Kougkas","H. Devarajan","X.-H. Sun","J. Lofstead"],"venue":"The IEEE International Conference on Cluster Computing 2018 (Cluster\'18), Belfast, UK2018. pp. 290-301.","type":"Conference","entryType":"inproceedings","date":"September, 2018","year":2018,"era":"iit","month":9,"doi":"10.1109/cluster.2018.00046","abstract":"Modern HPC systems employ burst buffer installations to reduce the peak I/O requirements for external storage and deal with the burstiness of I/O in modern scientific applications. These I/O buffering resources are shared between multiple applications that run concurrently. This leads to severe performance degradation due to contention, a phenomenon called cross-application I/O interference. In this paper, we first explore the negative effects of interference at the burst buffer layer and we present two new metrics that can quantitatively describe the slowdown applications experience due to interference. We introduce Harmonia, a new dynamic I/O scheduler that is aware of interference, adapts to the underlying system, implements a new 2-way decision-making process and employs several scheduling policies to maximize the system efficiency and applications\' performance. Our evaluation shows that Harmonia, through better I/O scheduling, can outperform by 3x existing state-of-the-art buffering management solutions and can lead to better resource utilization.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-harmonia-5ca9-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018hermes","slug":"kougkas-2018-hermes-25f4","title":"Hermes: A Heterogeneous-Aware Multi-Tiered Distributed I/O Buffering System","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The 27th ACM International Symposium on High-Performance Parallel and Distributed Computing (HPDC), Tempe, AZ, USA, 2018. pp. 219-230","type":"Conference","entryType":"inproceedings","date":"June, 2018","year":2018,"era":"iit","month":6,"doi":"10.1145/3208040.3208059","abstract":"Modern High-Performance Computing (HPC) systems are adding extra layers to the memory and storage hierarchy, named deep memory and storage hierarchy (DMSH), to increase I/O perfor- mance. New hardware technologies, such as NVMe and SSD, have been introduced in burst buffer installations to reduce the pressure for external storage and boost the burstiness of modern I/O systems. The DMSH has demonstrated its strength and potential in practice. However, each layer of DMSH is an independent heterogeneous system and data movement among more layers is significantly more complex even without considering heterogeneity. How to efficiently utilize the DMSH is a subject of research facing the HPC community. In this paper, we present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system. Hermes enables, manages, su- pervises, and, in some sense, extends I/O buffering to fully integrate into the DMSH. We introduce three novel data placement policies to efficiently utilize all layers and we present three novel techniques to perform memory, metadata, and communication management in hierarchical buffering systems. Our evaluation shows that, in ad- dition to automatic data movement through the hierarchy, Hermes can significantly accelerate I/O and outperforms by more than 2x state-of-the-art buffering platforms.","hasAbstract":true,"lede":"We present the design and implementa- tion of Hermes: a new, heterogeneous-aware, multi-tiered, dynamic, and distributed I/O buffering system.","links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-hermes-25f4-slides.pdf"},"tags":["Hermes"],"_projectIds":["hermes"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2018iris","slug":"kougkas-2018-iris-f1a6","title":"IRIS: I/O Redirection via Integrated Storage","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The 32nd ACM International Conference on Supercomputing (ICS), Bejing, China2018. pp. 33-42.","type":"Conference","entryType":"inproceedings","date":"June, 2018","year":2018,"era":"iit","month":6,"doi":"10.1145/3205289.3205322","abstract":"There is an ocean of available storage solutions in modern high-performance and distributed systems. These solutions consist of Par- allel File Systems (PFS) for the more traditional high-performance computing (HPC) systems and of Object Stores for emerging cloud environments. More often than not, these storage solutions are tied to specific APIs and data models and thus, bind developers, applications, and entire computing facilities to using certain inter-faces. Each storage system is designed and optimized for certain applications but does not perform well for others. Furthermore, modern applications have become more and more complex consist- ing of a collection of phases with different computation and I/O requirements. In this paper, we propose a unified storage access system, called IRIS (i.e., I/O Redirection via Integrated Storage). IRIS enables unified data access and seamlessly bridges the semantic gap between file systems and object stores. With IRIS, emerging High-Performance Data Analytics software has capable and diverse I/O support. IRIS can bring us closer to the convergence of HPC and Cloud environments by combining the best storage subsystems from both worlds. Experimental results show that IRIS can grant more than 7x improvement in performance than existing solutions.","hasAbstract":true,"lede":"We propose a unified storage access system, called IRIS (i.e., I/O Redirection via Integrated Storage).","links":{"pdf":"https://grc.iit.edu/papers/2018/kougkas-2018-iris-f1a6.pdf","slides":"https://grc.iit.edu/papers/2018/kougkas-2018-iris-f1a6-slides.pdf"},"_projectIds":["iris"],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"devarajan2017openethernet","slug":"devarajan-2017-open-ethernet-e0f1","title":"Open Ethernet Drive: Evolution of Energy-Ef\ufb01cient Storage Technology","authors":["H. Devarajan","A. Kougkas","X.-H. Sun","H. Che"],"venue":"The ACM SIGHPC 8th International Workshop on Data-Intensive Computing in the Clouds (DataCloud 2017), in conjunction with SC\'17, Denver, CO, USAvol. 17","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"An Open Ethernet Drive, also known as an OED, is a new technology that embeds a low-powered processor, a fixed-size memory and an Ethernet card on a disk drive (e.g. HDD or SSD). All major storage vendors have introduced their respective implementations with similar architectural designs. As the technology progresses into its second generation, the perfor- mance characteristics have improved substantially. In this study, we first demonstrate the differences between two generations of the OED technology. We run a variety of benchmarks and applications to thoroughly evaluate the performance of this device and its compatibility with the current ecosystem. Furthermore, we investigate the performance and energy footprint of the OED technology when used as a storage server and as an I/O accelerator. Evaluation results show that OED technology can be a reliable, scalable, energy and cost efficient storage solution. It is a viable replacement for storage servers offering competitive performance while consuming only 10% of the power that a typ- ical storage node needs. Finally, this study shows that OED\'s can be used as I/O accelerators capable of executing data-intensive computations (such as sorting, compression/decompression, etc.) on local data, whereby the expensive data movement is minimized resulting in low power consumption.","hasAbstract":true,"lede":"An Open Ethernet Drive, also known as an OED, is a new technology that embeds a low-powered processor, a fixed-size memory and an Ethernet card on a disk drive (e.g.","links":{"pdf":"https://grc.iit.edu/papers/2017/devarajan-2017-open-ethernet-e0f1.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2017enosis","slug":"kougkas-2017-enosis-ea06","title":"Enosis: Bridging the Semantic Gap between File-based and Object-based Data Models","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The ACM SIGHPC 8th International Workshop on Data-Intensive Computing in the Clouds (DataCloud 2017), in conjunction with SC\'17, Denver, CO, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"File and block storage are well-defined concepts in computing and have been used as common components of computer systems for decades. Big data has led to new types of storage. The predominant data model in cloud storage is the object-based storage and it is highly successful. Object stores follow a simpler API with get() and put() operations to interact with the data. A wide variety of data analysis software have been developed around objects using their APIs. However, object storage and traditional file storage are designed for different purpose and for different applications. Organizations maintain file-based storage clusters and a high volume of existing data are stored in files. Moreover, many new applications need to access data from both types of storage. In this paper, we first explore the key differences between object-based and the more traditional file-based storage systems. We have designed and implemented several file-to-object mapping algorithms to bridge the semantic gap between these data models. Our evaluation shows that by achieving an efficient such mapping, our library can grant 2x- 27x higher performance against a naive one-to-one mapping and with minimal overheads. Our study exposes various strengths and weaknesses of each mapping strategy and frames the extended potential of a unified data access system.","hasAbstract":true,"lede":"We first explore the key differences between object-based and the more traditional file-based storage systems.","links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-enosis-ea06.pdf","slides":"https://grc.iit.edu/papers/2017/kougkas-2017-enosis-ea06-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"},{"citeKey":"kougkas2017syndesis","slug":"kougkas-2017-syndesis-d59c","title":"Syndesis: Mapping Objects to Files for a Unified Data Access System","authors":["A. Kougkas","H. Devarajan","X.-H. Sun"],"venue":"The ACM SIGHPC 8th International Workshop on Many-Task Computing on Clouds, Grids, and Supercomputers (MTAGS 2017), in conjunction with SC\'17, Denver, CO, USA","type":"Workshop","entryType":"inproceedings","date":"November, 2017","year":2017,"era":"iit","month":11,"abstract":"The predominant data model in cloud storage is the object-based storage. Object stores follow a simpler API with get() and put() operations to interact with the data. A wide variety of data analysis software has been developed around objects using their APIs. In fact, the evolution of Big Data analytics is a major driver for highly optimized data-centric quality software. However, organizations maintain file-based storage clusters and a high volume of existing data are stored in files. This is specifically true for the scientific communities. In this paper, we present the key characteristics of object-based and file-based storage APIs, we explore several object-to-file mappings aiming to bridge the semantic gap between these data models. The evaluation of our mapping algorithms exposes various strengths and weaknesses of each strategy and frames the extended potential of a unified data access system. Results show that our solution can offer more than 3x higher performance for specific workloads while keeping minimal overhead of our library.","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2017/kougkas-2017-syndesis-d59c.pdf","slides":"https://grc.iit.edu/papers/2017/kougkas-2017-syndesis-d59c-slides.pdf"},"_projectIds":[],"_funding":[],"_fundingErrors":[],"grcSelected":false,"status":"published","visibility":"public"}]')}}]);